import{_ as a,o as r,c as t,a8 as i}from"./chunks/framework.CiGKN4gy.js";const b=JSON.parse('{"title":"3.x.x","description":"","frontmatter":{"title":"3.x.x","lang":"en"},"headers":[],"relativePath":"changes/3_x_x.md","filePath":"changes/3_x_x.md","lastUpdated":1790353258000}'),o={name:"changes/3_x_x.md"};function l(d,e,n,c,h,f){return r(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjIzLngueCUyMiUyQyUyMmxhbmclMjIlM0ElMjJlbiUyMiUyQyUyMmRhdGUlMjIlM0ExNzkwMzUzMjU4MDAwJTdE"},[...e[0]||(e[0]=[i('<h1 id="change-log-3-x-x" tabindex="-1">Change Log (3.x.x) <a class="header-anchor" href="#change-log-3-x-x" aria-label="Permalink to &quot;Change Log (3.x.x)&quot;">​</a></h1><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><div class="tip custom-block"><p class="custom-block-title">What is a breaking change?</p><ul><li>The original configuration file may not work, for example, if a directive item is removed or renamed.</li><li>It may be necessary to update the build environment, such as installing new dependencies.</li></ul></div><h2 id="_3-1-6-2021-03-07" tabindex="-1">[3.1.6] - 2021-03-07 <a class="header-anchor" href="#_3-1-6-2021-03-07" aria-label="Permalink to &quot;[3.1.6] - 2021-03-07&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Correcting the order in which rules take effect (<a href="https://github.com/ADD-SP/ngx_waf/commit/51c7824786c060f4b0dcffe77a4a1e04b775e04b" target="_blank" rel="noreferrer">51c7824</a>).</li></ul><h2 id="_3-1-5-2021-03-03" tabindex="-1">[3.1.5] - 2021-03-03 <a class="header-anchor" href="#_3-1-5-2021-03-03" aria-label="Permalink to &quot;[3.1.5] - 2021-03-03&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed a bug in the <code>config</code> script that caused dependencies to not be checked correctly (<a href="https://github.com/ADD-SP/ngx_waf/commit/075a27e4f7aaf7e78c45eac0c78c9634863be476#diff-b79606fb3afea5bd1609ed40b622142f1c98125abcfe89a76a661b0e8e343910" target="_blank" rel="noreferrer">075a27e</a>).</li></ul><hr><h2 id="_3-1-4-2021-03-02" tabindex="-1">[3.1.4] - 2021-03-02 <a class="header-anchor" href="#_3-1-4-2021-03-02" aria-label="Permalink to &quot;[3.1.4] - 2021-03-02&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Use safer string handling functions to avoid buffer overflows when conditions allow (<a href="https://github.com/ADD-SP/ngx_waf/commit/177ae68cb019f47096e6065ec34aa0ef9be07567" target="_blank" rel="noreferrer">177ae68</a>).</li></ul><hr><h2 id="_3-1-3-2021-02-23" tabindex="-1">[3.1.3] - 2021-02-23 <a class="header-anchor" href="#_3-1-3-2021-02-23" aria-label="Permalink to &quot;[3.1.3] - 2021-02-23&quot;">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Order of effectiveness of correction rules (<a href="https://github.com/ADD-SP/ngx_waf/commit/857ec84c6519d88d1c1a5560a244dceffd413f3f" target="_blank" rel="noreferrer">857ec84</a>).</li></ul><hr><h2 id="_3-1-2-2021-01-18" tabindex="-1">[3.1.2] - 2021-01-18 <a class="header-anchor" href="#_3-1-2-2021-01-18" aria-label="Permalink to &quot;[3.1.2] - 2021-01-18&quot;">​</a></h2><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed a bug that caused module initialization to fail when the rule file was not writable (<a href="https://github.com/ADD-SP/ngx_waf/commit/20acd27815d1f266d89c1557e93848c96117b8ff" target="_blank" rel="noreferrer">20acd27</a>).</li></ul><hr><h2 id="_3-1-1-2021-01-18" tabindex="-1">[3.1.1] - 2021-01-18 <a class="header-anchor" href="#_3-1-1-2021-01-18" aria-label="Permalink to &quot;[3.1.1] - 2021-01-18&quot;">​</a></h2><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Compatible with lower versions of gcc (<a href="https://github.com/ADD-SP/ngx_waf/commit/becbbe022b9f6efa606e720d7cbcd6c5d6f22c33" target="_blank" rel="noreferrer">becbbe0</a>).</li></ul><hr><h2 id="_3-1-0-2021-01-17" tabindex="-1">[3.1.0] - 2021-01-17 <a class="header-anchor" href="#_3-1-0-2021-01-17" aria-label="Permalink to &quot;[3.1.0] - 2021-01-17&quot;">​</a></h2><h3 id="note" tabindex="-1">Note <a class="header-anchor" href="#note" aria-label="Permalink to &quot;Note&quot;">​</a></h3><ul><li><code>v3.0.3</code> was skipped because a backward compatibility feature was added during the <code>v3.0.3</code> test.</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Add debug log for easy troubleshooting (<a href="https://github.com/ADD-SP/ngx_waf/commit/bac1d026e9e902d9a49881e899cba4965f3388a4" target="_blank" rel="noreferrer">bac1d02</a>).</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Fixed a segmentation fault (<a href="https://github.com/ADD-SP/ngx_waf/commit/57d7719654caddc40ee655c797f0984f42c25495" target="_blank" rel="noreferrer">57d7719</a>)。</p></li><li><p>More accurate visit frequency statistics (<a href="https://github.com/ADD-SP/ngx_waf/commit/53d3b149a524252dbb9b8170e31f4b1f4895a6b7" target="_blank" rel="noreferrer">53d3b14</a>).</p></li></ul><hr><h2 id="_3-0-2-2021-01-10" tabindex="-1">[3.0.2] - 2021-01-10 <a class="header-anchor" href="#_3-0-2-2021-01-10" aria-label="Permalink to &quot;[3.0.2] - 2021-01-10&quot;">​</a></h2><h3 id="note-1" tabindex="-1">Note <a class="header-anchor" href="#note-1" aria-label="Permalink to &quot;Note&quot;">​</a></h3><ul><li>Because of hotfixes performed on <code>v3.0.1</code>, all beta versions of <code>v3.0.2</code> are voided, please do not use these beta versions.</li></ul><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed a build error on <code>Alpine Linux</code> (<a href="https://github.com/ADD-SP/ngx_waf/commit/e989aa34370da73f03627601188ca33844372c4f" target="_blank" rel="noreferrer">e989aa3</a>).</li></ul><hr><h2 id="_3-0-1-2020-12-28" tabindex="-1">[3.0.1] - 2020-12-28 <a class="header-anchor" href="#_3-0-1-2020-12-28" aria-label="Permalink to &quot;[3.0.1] - 2020-12-28&quot;">​</a></h2><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed a segmentation fault when inspecting cookies (<a href="https://github.com/ADD-SP/ngx_waf/commit/8dc2b56e9a8ae7c22cc5309ac0a060b0358f545b" target="_blank" rel="noreferrer">8dc2b56</a>).</li></ul><hr><h2 id="_3-0-0-2020-12-25" tabindex="-1">[3.0.0] - 2020-12-25 <a class="header-anchor" href="#_3-0-0-2020-12-25" aria-label="Permalink to &quot;[3.0.0] - 2020-12-25&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p>Anti Challenge Collapsar now supports IPV6 (<a href="https://github.com/ADD-SP/ngx_waf/commit/00fbc1c20ec964f6cd3bb992d756737e95b6c7ed" target="_blank" rel="noreferrer">00fbc1c</a>).</p></li><li><p>IP black and white lists support IPV6, and can recognize IPV6 strings such as <code>fe80::/10</code> (<a href="https://github.com/ADD-SP/ngx_waf/commit/8519b26f5fb9491ac60ae084247a0957c0931d0c" target="_blank" rel="noreferrer">8519b26</a>).</p></li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p>Delete some meaningless logs (<a href="https://github.com/ADD-SP/ngx_waf/commit/bd279e7be872621fa75337722a9fae30b2ea6812" target="_blank" rel="noreferrer">bd279e7</a>).</p></li><li><p>Friendly error alerts (<a href="https://github.com/ADD-SP/ngx_waf/commit/d1185b26a413e45dcf5ef479b0078aa57a4b5962" target="_blank" rel="noreferrer">d1185b2</a> &amp; <a href="https://github.com/ADD-SP/ngx_waf/commit/f2b617d5174eb1bc6982113415ddcb1f798ef703" target="_blank" rel="noreferrer">f2b617d</a>). Warnings or error reporting when IP addresses in the rule file are invalid or IP address blocks overlap (does not detect all overlaps).</p></li><li><p>Faster IP matching (<a href="https://github.com/ADD-SP/ngx_waf/commit/2b9e77404826666df301c3d6b3ce07a6968de266" target="_blank" rel="noreferrer">2b9e774</a>).</p></li></ul><h3 id="fixed-8" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-8" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Fixed a bug that caused the cookie inspection not work (<a href="https://github.com/ADD-SP/ngx_waf/commit/87beed183e404c70411a2d35ea68ebbccccf5ff6" target="_blank" rel="noreferrer">87beed1</a>).</p></li><li><p>Modify the <code>config</code> file to ensure that the latest module code is compiled when executing <code>make</code> or <code>make modules</code> (<a href="https://github.com/ADD-SP/ngx_waf/commit/25f97f5e7f3792b131ab0ebb1bfe4b7fe5e330ae" target="_blank" rel="noreferrer">25f97f5</a>). Before the fix, if only the files under <code>inc/</code> changed, the latest code would not be compiled because the files under <code>inc/</code> were not checked for changes.</p></li><li><p>Fixed a bug with incorrect IPV4 segment identification (<a href="https://github.com/ADD-SP/ngx_waf/commit/73a22eb3538a24e9714bf8331946a5654df20cc1" target="_blank" rel="noreferrer">73a22eb</a>). This bug could cause the subnet mask not to be generated correctly when a rule like <code>192.168.0.0/10</code>, i.e. the suffix is not a multiple of 8, appears in the rule.</p></li></ul>',51)])])}const u=a(o,[["render",l]]);export{b as __pageData,u as default};
